META = {"chanctonbury":("Chanctonbury Ring",73,4.7),"owh":("Old Winchester Hill",66,7.0),"kithurst":("Kithurst Hill",77,4.5),"harting":("Harting Down",62,5.4),"bignor":("Bignor Hill",73,8.9)}
def parse(s): return [tuple(map(float,p.split(","))) for p in s.split()]

# 13 Nov (pm): take out the out-and-back detours (where the recorded track went off and came back on itself),
# so no screen shows the walk where Tony got lost. The real loop is untouched. Old Winchester Hill is a whole
# out-and-back router guess, so it is left as is and kept off the Today screens until real routes replace it.
import math as _math
def _m(a,b):
    kx=111320*_math.cos(_math.radians((a[1]+b[1])/2)); return _math.hypot((a[0]-b[0])*kx,(a[1]-b[1])*110540)
def despur(pts, tol=60, maxspan=14, maxreach=400):
    pts=list(pts); changed=True
    while changed:
        changed=False; n=len(pts)
        for i in range(n):
            for j in range(min(n-1,i+maxspan),i+1,-1):
                if i==0 and j>=n-2: continue
                if _m(pts[i],pts[j])<tol and max(_m(pts[i],p) for p in pts[i+1:j])<maxreach:
                    pts=pts[:i+1]+pts[j+1:]; changed=True; break
            if changed: break
    return pts
for _k in ("chanctonbury","harting","kithurst"):
    LOOPS[_k]=" ".join(f"{x:.4f},{y:.4f}" for x,y in despur(parse(LOOPS[_k])))
# Build 8 (14 Nov): demo loops snapped onto OSM foot ways (tools/walkdata/snap.py) replace the hand-traced lines
import os as _os, json as _json
_SN=_os.path.join(_os.path.dirname(_os.path.abspath(__file__)),"data","routes_snapped.json")
if _os.path.exists(_SN) and not _os.environ.get("HLID_NO_SNAP"):
    LOOPS.update(_json.load(open(_SN)))
